exercises.solution:
import bcrypt

def hacher(mdp):
    return bcrypt.hashpw(mdp.encode("utf-8"), bcrypt.gensalt())

def verifier(mdp, empreinte):
    return bcrypt.checkpw(mdp.encode("utf-8"), empreinte)

